"use client";

import { useEffect, useState } from "react";
import NotesGrid from "@/components/Notes/NotesGrid";

type Note = {
  id: number;
  content: string;
  date: string;
};

export default function Home() {
  const [noteList, setNoteList] = useState<Note[]>([]);
  const [selectedNoteId, setSelectedNoteId] = useState<number | null>(null);
  const [editingNoteId, setEditingNoteId] = useState<number | null>(null);
  const [isCreating, setIsCreating] = useState(false);

  useEffect(() => {
    const loadNotes = async () => {
      const response = await fetch("/api/notes");
      if (!response.ok) return;

      const data = await response.json();

      setNoteList(
        data.map(
          (note: { id: number; content: string; createdAt: string }) => ({
            id: note.id,
            content: note.content,
            date: new Date(note.createdAt).toLocaleString("en-US", {
              day: "numeric",
              month: "long",
              hour: "numeric",
              minute: "2-digit",
            }),
          }),
        ),
      );
    };

    loadNotes();
  }, []);

  const handleCreateNote = async (content: string) => {
    const response = await fetch("/api/notes", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ content }),
    });

    if (!response.ok) {
      console.error("Failed to create note:", await response.text());
      return;
    }

    const createdNote = await response.json();

    const newNote: Note = {
      id: createdNote.id,
      content: createdNote.content,
      date: "Just now",
    };

    setNoteList((currentNotes) => [newNote, ...currentNotes]);
    setSelectedNoteId(newNote.id);
    setIsCreating(false);
  };

  const handleEditNote = (id: number) => {
    setEditingNoteId(id);
    setSelectedNoteId(id);
  };

  const handleSaveNote = async (content: string) => {
    if (editingNoteId === null) return;

    const response = await fetch(`/api/notes/${editingNoteId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ content }),
    });

    if (!response.ok) {
      console.error("Failed to update note:", await response.text());
      return;
    }

    const updatedNote = await response.json();

    setNoteList((currentNotes) =>
      currentNotes.map((note) =>
        note.id === updatedNote.id
          ? { ...note, content: updatedNote.content }
          : note,
      ),
    );

    setEditingNoteId(null);
  };

  const handleDeleteNote = async (id: number) => {
    const response = await fetch(`/api/notes/${id}`, {
      method: "DELETE",
    });

    if (!response.ok) {
      console.error("Failed to delete note:", await response.text());
      return;
    }

    setNoteList((currentNotes) =>
      currentNotes.filter((note) => note.id !== id),
    );

    setSelectedNoteId(null);
    setEditingNoteId(null);
  };

  return (
    <main
      className="min-h-screen px-10 py-8"
      onClick={() => {
        setSelectedNoteId(null);
        setEditingNoteId(null);
        setIsCreating(false);
      }}
    >
      <header className="mb-6 flex items-center justify-between">
        <h1 className="text-[26px] font-semibold leading-8 text-gray-900">
          Notes
        </h1>

        <button
          type="button"
          aria-label="Create note"
          onClick={(event) => {
            event.stopPropagation();
            setIsCreating(true);
            setEditingNoteId(null);
            setSelectedNoteId(null);
          }}
          className="flex h-10 w-10 items-center justify-center rounded-full bg-gray-900 text-2xl font-light leading-none text-white transition-colors hover:bg-gray-800"
        >
          +
        </button>
      </header>

      <div onClick={(event) => event.stopPropagation()}>
        <NotesGrid
          notes={noteList}
          selectedNoteId={selectedNoteId}
          editingNoteId={editingNoteId}
          isCreating={isCreating}
          onCreate={handleCreateNote}
          onCancelCreate={() => setIsCreating(false)}
          onSelect={(id) => {
            setSelectedNoteId(id);
            setEditingNoteId(null);
          }}
          onEdit={handleEditNote}
          onSave={handleSaveNote}
          onCancelEdit={() => setEditingNoteId(null)}
          onDelete={handleDeleteNote}
        />
      </div>
    </main>
  );
}
